import java.util.stream.*;
import java.util.*;

record Venta(String producto, String region, double monto) {}

List<Venta> ventas = List.of(
    new Venta("A", "Norte", 100),
    new Venta("B", "Sur", 200),
    new Venta("A", "Sur", 150)
);

// groupingBy con downstream
Map<String, Long> conteoPorRegion = ventas.stream()
    .collect(Collectors.groupingBy(Venta::region, Collectors.counting()));

// groupingBy con mapping
Map<String, List<String>> productosPorRegion = ventas.stream()
    .collect(Collectors.groupingBy(
        Venta::region,
        Collectors.mapping(Venta::producto, Collectors.toList())
    ));

// partitioningBy
Map<Boolean, List<Venta>> porMonto = ventas.stream()
    .collect(Collectors.partitioningBy(v -> v.monto() > 120));

// toMap con merge function para duplicados
Map<String, Double> totalPorProducto = ventas.stream()
    .collect(Collectors.toMap(
        Venta::producto,
        Venta::monto,
        Double::sum  // merge: sumar si hay duplicados
    ));

