import java.util.concurrent.*;
import java.util.stream.*;
import java.util.*;

// ForkJoinPool personalizado (4 hilos para I/O)
ForkJoinPool pool = new ForkJoinPool(4);
List<String> archivos = List.of("a.txt", "b.txt", "c.txt");

// Ejecutar I/O en pool dedicado
List<String> contenidos = pool.submit(() ->
    archivos.parallelStream()
        .map(this::leerArchivo) // I/O pesado
        .toList()
).get();

pool.shutdown();

// CompletableFuture: control mas granular
CompletableFuture<List<String>> future =
    CompletableFuture.supplyAsync(() -> archivos.stream()
        .map(this::leerArchivo)
        .toList(), pool);

// No usar parallelStream para I/O
